import{_ as a,a as t,c as o,ac as l}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第二册：实践与进步 · Lesson 76 April Fools' Day","description":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 76 April Fools' Day","description":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 75 SOS","link":"/life/english/new-concept/book-2/unit-04/lesson-075"},"next":{"text":"第二册：实践与进步 · Lesson 77 A successful operation","link":"/life/english/new-concept/book-2/unit-04/lesson-077"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 75 SOS","link":"/life/english/new-concept/book-2/unit-04/lesson-075"},"next":{"text":"第二册：实践与进步 · Lesson 77 A successful operation","link":"/life/english/new-concept/book-2/unit-04/lesson-077"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-076.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-076.md"}`),n={name:"life/english/new-concept/book-2/unit-04/lesson-076.md"};function i(r,e,s,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="第二册-实践与进步-·-lesson-76-april-fools-day" tabindex="-1">第二册：实践与进步 · Lesson 76 April Fools&#39; Day <a class="header-anchor" href="#第二册-实践与进步-·-lesson-76-april-fools-day" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 76 April Fools&#39; Day&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>玩笑报道可能被误当成事实，读者需要查日期和独立来源；练习转述声称而不背书。本课的语言观察是：claimed that 明确有人作出声称，不等于内容成立；reported that 也不自动保证真实，应结合来源和验证信息。完成学习后，请写一个识别虚构报道的过程，区分声称、核查和最后确认。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>fool</td><td>/fuːl/</td><td>v.</td><td>愚弄</td><td>fool an audience</td></tr><tr><td>broadcast</td><td>/ˈbrɔːdkɑːst/</td><td>n.</td><td>广播节目</td><td>a live broadcast</td></tr><tr><td>harvest</td><td>/ˈhɑːvɪst/</td><td>n.</td><td>收获</td><td>a good harvest</td></tr><tr><td>believe</td><td>/bɪˈliːv/</td><td>v.</td><td>相信</td><td>believe a story</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>fall for a story — 轻信一个故事</li><li>check the source — 核对来源，不等于只看标题</li></ul><h2 id="语法讲解-间接引语与视角转换" tabindex="-1">语法讲解：间接引语与视角转换 <a class="header-anchor" href="#语法讲解-间接引语与视角转换" aria-label="Permalink to &quot;语法讲解：间接引语与视角转换&quot;">​</a></h2><p>转述他人的话需要调整人称、时间和地点参照。主句为过去时且从过去视角回顾时，从句常相应后移时态；内容仍然有效或属于一般事实时，也可以保留现在时。陈述用 that 从句，是否问句用 if/whether，特殊疑问保留疑问词。转述疑问一律采用陈述语序，不保留原问句的助动词倒装；不能只换引号而不考虑说话视角。本课应用：claimed that 明确有人作出声称，不等于内容成立；reported that 也不自动保证真实，应结合来源和验证信息。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The programme claimed that the trees could grow blue apples.</p></blockquote><p>节目声称那些树能结出蓝色苹果。</p><p>claimed 为报告动词，that 从句是被声称的内容；could 是从过去视角表达能力，句子不证明该能力真实。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>believe a person 表相信其所说，believe in a person 更偏信任其能力或品格。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>重读 claimed 与 joke，避免把从句读成作者认可的事实；注意 apples 的复数 /z/。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The programme claimed that the trees could grow blue apples. I checked the date before sharing it. The next programme explained that the story was a joke.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一个识别虚构报道的过程，区分声称、核查和最后确认。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：claimed 为报告动词，that 从句是被声称的内容；could 是从过去视角表达能力，句子不证明该能力真实。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：believe a person 表相信其所说，believe in a person 更偏信任其能力或品格。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 that/what：The report claimed ___ the fruit was blue.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> that</p><p><strong>解析：</strong> 从句结构完整，用 that 引出内容。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>说话者分享前核对了什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The date.</p><p><strong>解析：</strong> 下一期解释是玩笑，前一句核对的是日期。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把“她轻信了那个故事”译成含 fall for 的句子。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She fell for the story.</p><p><strong>解析：</strong> fall 的过去式为 fell，此处短语表示轻信。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：间接引语与视角转换。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-075">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-077">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(n,[["render",i]]);export{u as __pageData,b as default};
